use std::fmt::Write;

fn main() {
    // Compute first 61 fusc numbers
    let mut memo: Vec<Option<u128>> = vec![None; 61];
    memo[0] = Some(0);
    memo[1] = Some(1);

    fn fusc(n: usize, memo: &mut Vec<Option<u128>>) -> u128 {
        if let Some(v) = memo[n] {
            return v;
        }
        let res = if n % 2 == 0 {
            fusc(n / 2, memo)
        } else {
            fusc((n - 1) / 2, memo) + fusc((n + 1) / 2, memo)
        };
        memo[n] = Some(res);
        res
    }

    for i in 0..61 {
        fusc(i, &mut memo);
    }

    // Build first line
    let mut first_line = String::new();
    for (idx, val) in memo.iter().enumerate() {
        if idx > 0 {
            first_line.push(' ');
        }
        write!(&mut first_line, "{:,}", val.unwrap()).unwrap();
    }
    println!("{}", first_line);

    // Find the first index where length > all previous lengths
    let mut max_len = 0usize;
    let mut record_idx: Option<usize> = None;
    let mut record_val: Option<u128> = None;
    for (idx, val_opt) in memo.iter().enumerate() {
        let val = val_opt.unwrap();
        let len = val.to_string().len();
        if len > max_len {
            max_len = len;
            record_idx = Some(idx);
            record_val = Some(val);
        }
    }

    if let (Some(idx), Some(val)) = (record_idx, record_val) {
        println!("{} {}", idx, format!("{:,}", val));
    }
}

