use std::fmt::Write;

fn main() {
    const N: usize = 61; // number of terms to output
    let mut fusc = vec![0u64; N];
    fusc[0] = 0;
    if N > 1 {
        fusc[1] = 1;
    }
    for i in 2..N {
        if i % 2 == 0 {
            fusc[i] = fusc[i / 2];
        } else {
            fusc[i] = fusc[(i - 1) / 2] + fusc[(i + 1) / 2];
        }
    }

    // First line: all terms separated by whitespace
    let mut first_line = String::new();
    for (idx, &val) in fusc.iter().enumerate() {
        if idx > 0 {
            first_line.push(' ');
        }
        write!(&mut first_line, "{}", val).unwrap();
    }
    println!("{}", first_line);

    // Find the first term whose decimal length exceeds all previous lengths
    let mut max_len = 1usize; // length of "0"
    let mut max_index = 0usize;
    for (idx, &val) in fusc.iter().enumerate() {
        let len = if val == 0 { 1 } else { ((val as f64).log10().floor() as usize) + 1 };
        if len > max_len {
            max_len = len;
            max_index = idx;
        }
    }
    println!("{} {}", max_index, fusc[max_index]);
}

